                    ctx.quadraticCurveTo(ox + JS.cos(a) * l * 0.5 + (r() - 0.5) * l * 0.2, oy + JS.sin(a) * l * 0.5, ox + JS.cos(a) * l, oy + JS.sin(a) * l * ((up ? 0.8 : 1.0)))
                }
            }
            ctx.stroke()
            ctx.globalAlpha = 1.0
        }
        let n: Double = JS.max(2.0, JS.round(3.0 + 8.0 * g))
        let tsz: Double = hh * 0.055
        do {
            var i: Double = 0.0
            while i < n {
                defer { i += 1 }
                let u: Double = 0.28 + 0.68 * JS.pow(i / JS.max(1.0, n - 1.0), 0.9)
                let _d3 = tp(u)
                let tx: Double = _d3.0
                let ty: Double = _d3.1
                let side: Double = (r() < 0.66 ? -(1.0) : 1.0)
                let len: Double = hh * (0.42 * (1.0 - u) + 0.1) * ((side < 0.0 ? 1.25 : 0.75)) * (0.8 + r() * 0.4)
                let rise: Double = -hh * (0.03 + r() * 0.04)
                let ex: Double = tx + side * len
