                ctx.quadraticCurveTo(cx, cy, ex, ey)
                ctx.stroke()
                let m: Double = JS.max(3.0, JS.round(len / (tsz * 0.55)))
                do {
                    var k: Double = 0.0
                    while k < m {
                        defer { k += 1 }
                        let v: Double = 0.35 + 0.65 * (k / (m - 1.0))
                        let bxp: Double = (1.0 - v) * (1.0 - v) * tx + 2.0 * (1.0 - v) * v * cx + v * v * ex
                        let byp: Double = (1.0 - v) * (1.0 - v) * ty + 2.0 * (1.0 - v) * v * cy + v * v * ey
                        let sz: Double = tsz * (0.75 + JS.sin(v * Double.pi) * 0.6) * (0.85 + r() * 0.3)
                        tuft(bxp + (r() - 0.5) * tsz * 0.4, byp - sz * 0.1 + (r() - 0.5) * tsz * 0.2, sz)
                        if r() < 0.45 {
                            tuft(bxp + (r() - 0.5) * tsz, byp - sz * 0.35, sz * 0.7)
                        }
                    }
                }
            }
        }
        let top: (Double, Double) = tp(1.0)
        do {
            var k: Double = 0.0
            while k < 5.0 {
                defer { k += 1 }
                tuft(top.0 + (r() - 0.5) * tsz * 1.6, top.1 + (r() - 0.2) * tsz * 0.6, tsz * (0.9 + r() * 0.4))
            }
        }
    }
    static func paintNear(_ ctx: C2D, _ w: Double, _ h: Double, _ L: Layout, _ pal: Pal, _ r: () -> Double, _ seed: Double, _ S: RScene) {
        let sx: Double = seed * 5.3
        func top(_ x: Double) -> Double {
            return L.ledgeTop + (fbm1(x / (w * 0.05) + sx, 6.0, true) - 0.5) * h * 0.035 + JS.max(0.0, (L.ledgeX + w * 0.06 - x) / (w * 0.06)) * h * 0.06
        }
        var edge: [(Double, Double)] = ([] as [(Double, Double)])
        do {
            var i: Double = 0.0
            while i <= 30.0 {
                defer { i += 1 }
                let u: Double = i / 30.0
                edge.append((L.ledgeX + (fbm1(u * 6.0 + sx + 3.0, 5.0) - 0.5) * w * 0.05 + u * u * w * 0.02, h + 2.0 - u * (h + 2.0 - top(L.ledgeX + w * 0.02))))
            }
        }
        let shelf: [(Double, Double)] = ridgePts(L.ledgeX + w * 0.02, w * 1.05, 120.0, { (x: Double, _ _x0: Double) -> Double in
            return top(x)
        })
        let poly: [(Double, Double)] = (Array(edge) + Array(shelf) + ([(w * 1.05, h + 2.0)] as [(Double, Double)]))
        wash(ctx, poly, pal.near, r, O_body_layers_a_v_edge(body: 0.94, layers: 10.0, a: 0.06, v: 0.004, edge: 0.2))
        ctx.strokeStyle = C2DStyle(css(mixc(pal.near, pal.rockLight, 0.35), 0.35))
        ctx.lineWidth = JS.max(1.0, w / 900.0)
        do {
            var i: Double = 0.0
            while i < 26.0 {
                defer { i += 1 }
                let x0: Double = L.ledgeX + r() * w * 0.35
                let y0: Double = top(x0) + r() * (h - top(x0))
                ctx.beginPath()
                ctx.moveTo(x0, y0)
                var px: Double = x0
                var py: Double = y0
                do {
                    var k: Double = 0.0
                    while k < 5.0 {
                        defer { k += 1 }
                        px += w * 0.012 * (0.5 + r())
                        py += (r() - 0.35) * h * 0.012
                        ctx.lineTo(px, py)
                    }
                }
                ctx.stroke()
            }
        }
        let n: Double = JS.min(7.0, S.rubble)
        do {
            var i: Double = 0.0
            while i < n {
                defer { i += 1 }
                let rr: () -> Double = rng(seed * 31.0 + i * 7.0)
                let u: Double = (L.tall ? ([0.1, 0.2, 0.66, 0.74, 0.04, 0.6, 0.28] as [Double])[Int(i)] : ([0.53, 0.585, 0.785, 0.745, 0.505, 0.83, 0.61] as [Double])[Int(i)])
                let x: Double = u * w
                let s2: Double = L.rockW * (0.2 + rr() * 0.1)
                let y: Double = top(x) + s2 * 0.1
                for side in ([-(1.0), 1.0] as [Double]) {
                    var pts: [(Double, Double)] = ([] as [(Double, Double)])
                    let m: Double = 8.0
                    do {
                        var k: Double = 0.0
                        while k <= m {
                            defer { k += 1 }
                            let a: Double = Double.pi + (k / m) * Double.pi
                            let rad: Double = 0.75 + rr() * 0.3
                            pts.append((x + side * s2 * 0.32 + JS.cos(a) * s2 * 0.42 * rad, y + JS.sin(a) * s2 * 0.5 * rad * ((side < 0.0 ? 1.0 : 0.8))))
                        }
                    }
                    let body: (Double, Double, Double) = mixc(pal.rock, pal.near, 0.45)
                    ctx.fillStyle = C2DStyle(css(body))
                    fillPoly(ctx, deform(pts, 1.0, 0.03, rr))
                    ctx.save()
                    ctx.beginPath()
                    ctx.moveTo((pts[0]).0, (pts[0]).1)
                    for p in pts {
                        ctx.lineTo(p.0, p.1)
                    }
                    ctx.closePath()
                    ctx.clip()
                    let gr: C2DGradient = ctx.createLinearGradient(0.0, y - s2 * 0.5, 0.0, y)
                    gr.addColorStop(0.0, css(pal.rockLight, 0.35))
                    gr.addColorStop(1.0, css(pal.near, 0.5))
                    ctx.fillStyle = C2DStyle(gr)
                    ctx.fillRect(x - s2, y - s2, s2 * 2.0, s2)
                    ctx.restore()
                }
            }
        }
        paintPine(ctx, L.treeX, top(L.treeX) + h * 0.004, L.treeH, S.tree, pal.near, r, w / 1000.0)
        granulate(ctx, w, h, 0.15)
    }
    static func boulderOf(_ L: Layout, _ seed: Double, _ w: Double, _ h: Double) -> Boulder {
        let r: () -> Double = rng(seed * 13.0 + 5.0)
        let bw: Double = L.rockW
        let bh: Double = bw * 0.8
        let cx: Double = L.rockX
        let by: Double = L.ledgeTop + h * 0.01
        let cy: Double = by - bh * 0.42
        var outline: [(Double, Double)] = ([] as [(Double, Double)])
        let M: Double = 56.0
        do {
            var k: Double = 0.0
            while k < M {
                defer { k += 1 }
                let a: Double = (k / M) * Double.pi * 2.0
                let rad: Double = 1.0 + (fbm1(k * 0.22 + seed * 1.7, 4.0) - 0.5) * 0.24 + (fbm1(k * 0.9 + seed, 2.0) - 0.5) * 0.05
                let sq: Double = 1.0
                outline.append((cx + JS.cos(a) * bw * 0.5 * rad, JS.min(by + 2.0, cy + JS.sin(a) * bh * 0.55 * rad * sq)))
            }
        }
        func topAt(_ x: Double) -> Double {
            var best: Double = by
            for p in outline {
                if (JS.abs(p.0 - x) < bw * 0.04 && p.1 < best) {
                    best = p.1
                }
            }
            return best
        }
        var cracks: [[(Double, Double)]] = ([] as [[(Double, Double)]])
        let starts: [Double] = ([0.5, 0.3, 0.68, 0.4, 0.6] as [Double])
        do {
            var c: Double = 0.0
            while c < 5.0 {
                defer { c += 1 }
                var pts: [(Double, Double)] = ([] as [(Double, Double)])
                let sx: Double = cx + (starts[Int(c)] - 0.5) * bw * 0.9
                var x: Double = sx
                var y: Double = topAt(sx) + bh * 0.02
                let end: Double = (c == 0.0 ? by : y + bh * (0.3 + r() * 0.25))
                let drift: Double = (c == 0.0 ? 0.0 : (((JSMath.rem(c, 2.0)) != 0 ? -(1.0) : 1.0)) * bw * 0.06)
                pts.append((x, y))
                let steps: Double = (c == 0.0 ? 14.0 : 8.0)
                do {
                    var k: Double = 1.0
                    while k <= steps {
                        defer { k += 1 }
                        y += (end - y) / (steps - k + 1.0)
                        x += drift / steps + (r() - 0.5) * bw * 0.05
                        pts.append((x, y))
                    }
                }
                cracks.append(pts)
            }
        }
        return Boulder(outline: outline, cracks: cracks, cx: cx, by: by, bw: bw, bh: bh)
    }
    static func partial(_ pts: [(Double, Double)], _ p: Double) -> [(Double, Double)] {
        if p >= 1.0 {
            return pts
        }
        let n: Double = (Double(pts.count) - 1.0) * JS.max(0.0, p)
        let k: Double = JS.floor(n)
        let f: Double = n - k
        var out: [(Double, Double)] = JS.slice(pts, 0.0, k + 1.0)
        if k < Double(pts.count) - 1.0 {
            out.append(((pts[Int(k)]).0 + ((pts[Int(k + 1.0)]).0 - (pts[Int(k)]).0) * f, (pts[Int(k)]).1 + ((pts[Int(k + 1.0)]).1 - (pts[Int(k)]).1) * f))
        }
        return out
    }
    static func paintBoulder(_ ctx: C2D, _ w: Double, _ h: Double, _ L: Layout, _ pal: Pal, _ seed: Double, _ S: RScene) {
        let B: Boulder = boulderOf(L, seed, w, h)
        let r: () -> Double = rng(seed * 7.0 + 1.0)
        let drop: Double = (S.rockIn != nil ? -(JS.pow(1.0 - S.rockIn!, 2.0)) * h * 0.25 : 0.0)
        let halves: [Double] = (S.broken > 0.001 ? ([-(1.0), 1.0] as [Double]) : ([0.0] as [Double]))
        let shadow: C2DGradient = ctx.createRadialGradient(B.cx + B.bw * 0.08, B.by, 0.0, B.cx + B.bw * 0.08, B.by, B.bw * 0.7)
        shadow.addColorStop(0.0, css(pal.near, 0.75))
        shadow.addColorStop(1.0, css(pal.near, 0.0))
        ctx.save()
        ctx.translate(B.cx, B.by)
