                    ctx.lineTo(p.0, p.1)
                }
                ctx.lineTo((c0[Int(Double(c0.count) - 1.0)]).0, B.by + 4.0)
                ctx.lineTo(B.cx + side * B.bw, B.by + 4.0)
                ctx.lineTo(B.cx + side * B.bw, B.by - B.bh * 1.5)
                ctx.closePath()
                ctx.clip()
            }
            ctx.translate(0.0, drop)
            let body: [(Double, Double)] = B.outline
            ctx.fillStyle = C2DStyle(css(pal.rock))
            fillPoly(ctx, body)
            ctx.save()
            ctx.beginPath()
            ctx.moveTo((body[0]).0, (body[0]).1)
            for p in body {
                ctx.lineTo(p.0, p.1)
            }
            ctx.closePath()
            ctx.clip()
            let hx: Double = B.cx - B.bw * 0.2
            let hy: Double = B.by - B.bh * 0.78
            let lg: C2DGradient = ctx.createRadialGradient(hx, hy, 0.0, hx, hy, B.bw * 0.7)
            lg.addColorStop(0.0, css(pal.rockLight, 0.95))
            lg.addColorStop(0.5, css(pal.rockLight, 0.35))
            lg.addColorStop(1.0, css(pal.rockLight, 0.0))
            ctx.fillStyle = C2DStyle(lg)
            ctx.fillRect(B.cx - B.bw, B.by - B.bh * 1.5, B.bw * 2.0, B.bh * 1.6)
            let dg: C2DGradient = ctx.createLinearGradient(B.cx - B.bw * 0.2, B.by - B.bh * 0.7, B.cx + B.bw * 0.3, B.by)
            dg.addColorStop(0.0, css(pal.rockDark, 0.0))
            dg.addColorStop(0.55, css(pal.rockDark, 0.35))
            dg.addColorStop(1.0, css(pal.rockDark, 0.95))
            ctx.fillStyle = C2DStyle(dg)
            ctx.fillRect(B.cx - B.bw, B.by - B.bh * 1.5, B.bw * 2.0, B.bh * 1.6)
            do {
                var k: Double = 0.0
                while k < 10.0 {
                    defer { k += 1 }
                    let px: Double = B.cx + (r() - 0.5) * B.bw * 0.9
                    let py: Double = B.by - r() * B.bh * 0.9
                    let rw: Double = B.bw * (0.08 + r() * 0.16)
                    var pts: [(Double, Double)] = ([] as [(Double, Double)])
                    do {
                        var q: Double = 0.0
                        while q < 9.0 {
                            defer { q += 1 }
                            let a: Double = (q / 9.0) * Double.pi * 2.0
                            pts.append((px + JS.cos(a) * rw * (0.6 + r() * 0.5), py + JS.sin(a) * rw * 0.5 * (0.6 + r() * 0.5)))
                        }
                    }
                    ctx.globalAlpha = 0.12
                    ctx.fillStyle = C2DStyle(css((r() < 0.5 ? pal.rockDark : pal.rockLight)))
                    fillPoly(ctx, deform(pts, 2.0, 0.06, r))
                }
            }
            ctx.globalAlpha = 0.28
            ctx.strokeStyle = C2DStyle(css(pal.rockDark))
            ctx.lineWidth = JS.max(0.8, B.bw * 0.006)
            do {
                var k: Double = 0.0
                while k < 7.0 {
                    defer { k += 1 }
                    let px: Double = B.cx + (r() - 0.5) * B.bw * 0.8
                    let py: Double = B.by - (0.15 + r() * 0.7) * B.bh
                    ctx.beginPath()
                    ctx.moveTo(px, py)
                    ctx.lineTo(px + B.bw * (0.05 + r() * 0.12), py + (r() - 0.3) * B.bh * 0.12)
                    ctx.stroke()
                }
            }
            do {
                var k: Double = 0.0
                while k < 120.0 {
                    defer { k += 1 }
                    let x: Double = B.cx + (r() - 0.5) * B.bw
                    let y: Double = B.by - r() * B.bh
                    ctx.globalAlpha = 0.3
                    ctx.fillStyle = C2DStyle((r() < 0.6 ? css(pal.rockDark) : css(pal.rockLight)))
                    ctx.beginPath()
                    ctx.arc(x, y, JS.max(0.5, r() * B.bw * 0.006), 0.0, Double.pi * 2.0)
                    ctx.fill()
                }
            }
            ctx.globalAlpha = 1.0
            ctx.restore()
            ctx.globalAlpha = 0.35
            ctx.strokeStyle = C2DStyle(css(pal.rockDark))
            ctx.lineWidth = JS.max(1.0, B.bw * 0.008)
            ctx.beginPath()
