            }
            ctx.closePath()
            ctx.stroke()
            ctx.globalAlpha = 1.0
            let lw: Double = JS.max(1.2, B.bw * 0.013)
            do {
                var c: Double = 0.0
                while c < 5.0 {
                    defer { c += 1 }
                    let p: Double = JS.min(1.0, JS.max(0.0, S.cracks - c))
