                    ctx.lineWidth = lw * 0.7
                    ctx.beginPath()
                    fe4: for (_ii, q) in pts.enumerated() {
                        let i = Double(_ii)
                        if i != 0 {
                            ctx.lineTo(q.0 - lw * 0.75, q.1 - lw * 0.4)
                        } else {
                            ctx.moveTo(q.0 - lw * 0.75, q.1 - lw * 0.4)
                        }
                    }
                    ctx.stroke()
                    ctx.strokeStyle = C2DStyle(css(pal.crack, 0.95))
                    ctx.lineWidth = lw * ((c == 0.0 ? 1.4 : 1.0))
                    ctx.beginPath()
                    fe5: for (_ii, q) in pts.enumerated() {
                        let i = Double(_ii)
                        if i != 0 {
                            ctx.lineTo(q.0, q.1)
                        } else {
                            ctx.moveTo(q.0, q.1)
                        }
                    }
                    ctx.stroke()
                    ctx.lineWidth = lw * 0.4
                    do {
                        var k: Double = 2.0
                        while k < Double(pts.count) - 1.0 {
                            defer { k += 3.0 }
                            let q: (Double, Double) = pts[Int(k)]
                            let d: Double = (((JSMath.rem(k, 2.0)) != 0 ? 1.0 : -(1.0))) * B.bw * 0.045
                            ctx.beginPath()
                            ctx.moveTo(q.0, q.1)
                            ctx.lineTo(q.0 + d, q.1 + B.bh * 0.035)
                            ctx.lineTo(q.0 + d * 1.5, q.1 + B.bh * 0.025)
                            ctx.stroke()
                        }
                    }
                }
            }
            ctx.restore()
        }
        if S.broken > 0.3 {
            do {
                var k: Double = 0.0
                while k < 8.0 {
                    defer { k += 1 }
                    let x: Double = B.cx + (r() - 0.5) * B.bw * 1.1
                    let s2: Double = B.bw * (0.02 + r() * 0.035)
                    ctx.fillStyle = C2DStyle(css(mixc(pal.rock, pal.near, 0.3), JS.min(1.0, (S.broken - 0.3) * 2.0)))
                    ctx.beginPath()
                    ctx.moveTo(x - s2, B.by + 1.0)
                    ctx.lineTo(x - s2 * 0.3, B.by - s2 * 0.9)
                    ctx.lineTo(x + s2, B.by - s2 * 0.3)
                    ctx.lineTo(x + s2 * 0.8, B.by + 1.0)
                    ctx.closePath()
                    ctx.fill()
                }
            }
        }
    }
    static func boulderGeom(_ w: Double, _ h: Double, _ seed: Double) -> Boulder {
        return boulderOf(layoutFor(w, h), seed, w, h)
    }
    static func paintMist(_ ctx: C2D, _ w: Double, _ h: Double, _ ys: [Double], _ pal: Pal, _ r: () -> Double) {
        for y in ys {
            do {
                var i: Double = 0.0
                while i < 22.0 {
                    defer { i += 1 }
                    let cx: Double = r() * w
                    let cy: Double = y + (r() - 0.5) * h * 0.06
                    let cw: Double = w * (0.12 + r() * 0.22)
                    let ch: Double = h * (0.02 + r() * 0.035)
                    let g: C2DGradient = ctx.createRadialGradient(cx, cy, 0.0, cx, cy, cw)
                    g.addColorStop(0.0, css(pal.mist, 0.5))
                    g.addColorStop(1.0, css(pal.mist, 0.0))
                    ctx.save()
                    ctx.translate(cx, cy)
                    ctx.scale(1.0, ch / cw)
                    ctx.translate(-cx, -cy)
                    ctx.fillStyle = C2DStyle(g)
                    ctx.beginPath()
                    ctx.arc(cx, cy, cw, 0.0, Double.pi * 2.0)
                    ctx.fill()
                    ctx.restore()
                }
            }
        }
    }
    static func drawChips(_ ctx: C2D, _ w: Double, _ h: Double, _ seed: Double, _ at: (Double, Double), _ bt: Double, _ theme: String) {
        if (bt < 0.0 || bt > 1.4) {
            return
        }
        let r: () -> Double = rng(seed * 3.0 + 11.0)
        let pal: Pal = palette(theme, 0.0)
        let s: Double = JS.min(w, h)
        do {
            var i: Double = 0.0
            while i < 16.0 {
                defer { i += 1 }
                let a: Double = -Double.pi * (0.15 + r() * 0.7)
                let v: Double = s * (0.25 + r() * 0.5)
                let x: Double = at.0 + JS.cos(a) * v * bt
                let y: Double = at.1 + JS.sin(a) * v * bt + 0.9 * s * bt * bt
                let z: Double = s * (0.004 + r() * 0.006)
                ctx.fillStyle = C2DStyle(css(((JSMath.rem(i, 3.0)) != 0 ? pal.rockDark : pal.rockLight), JS.max(0.0, 1.0 - bt / 1.4)))
                ctx.beginPath()
                ctx.moveTo(x - z, y)
                ctx.lineTo(x, y - z)
                ctx.lineTo(x + z, y + z * 0.4)
                ctx.closePath()
                ctx.fill()
            }
        }
        let g: C2DGradient = ctx.createRadialGradient(at.0, at.1, 0.0, at.0, at.1, s * 0.12 * (0.4 + bt))
        g.addColorStop(0.0, css(pal.mist, 0.35 * JS.max(0.0, 1.0 - bt / 1.2)))
        g.addColorStop(1.0, css(pal.mist, 0.0))
        ctx.fillStyle = C2DStyle(g)
        ctx.fillRect(at.0 - s * 0.3, at.1 - s * 0.3, s * 0.6, s * 0.6)
    }
